CREATE TYPE public.app_role AS ENUM ('admin','user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, full_name text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '');
GRANT SELECT,INSERT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile ON public.profiles FOR ALL TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE TABLE public.addresses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL, full_name text NOT NULL, phone text NOT NULL, province text NOT NULL,city text NOT NULL,address text NOT NULL,postal_code text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.addresses TO authenticated; GRANT ALL ON public.addresses TO service_role;
ALTER TABLE public.addresses ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_addresses ON public.addresses FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid()); CREATE INDEX addresses_user_idx ON public.addresses(user_id);
CREATE TABLE public.wishlist (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,product_handle text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,product_handle));
GRANT SELECT,INSERT,DELETE ON public.wishlist TO authenticated; GRANT ALL ON public.wishlist TO service_role;
ALTER TABLE public.wishlist ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_wishlist ON public.wishlist FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.newsletter_subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),contact text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now());
GRANT INSERT ON public.newsletter_subscriptions TO anon,authenticated; GRANT SELECT,DELETE ON public.newsletter_subscriptions TO authenticated; GRANT ALL ON public.newsletter_subscriptions TO service_role;
ALTER TABLE public.newsletter_subscriptions ENABLE ROW LEVEL SECURITY;
CREATE POLICY subscribe ON public.newsletter_subscriptions FOR INSERT TO anon,authenticated WITH CHECK(length(contact) BETWEEN 8 AND 254);
CREATE POLICY admin_subscriptions ON public.newsletter_subscriptions FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.contact_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,email text NOT NULL,message text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT INSERT ON public.contact_messages TO anon,authenticated; GRANT SELECT,DELETE ON public.contact_messages TO authenticated; GRANT ALL ON public.contact_messages TO service_role;
ALTER TABLE public.contact_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY send_message ON public.contact_messages FOR INSERT TO anon,authenticated WITH CHECK(length(name) BETWEEN 2 AND 100 AND length(message) BETWEEN 10 AND 5000 AND length(email) BETWEEN 5 AND 254);
CREATE POLICY admin_messages ON public.contact_messages FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.store_settings (key text PRIMARY KEY,value text NOT NULL DEFAULT '');
GRANT SELECT ON public.store_settings TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.store_settings TO authenticated; GRANT ALL ON public.store_settings TO service_role;
ALTER TABLE public.store_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_settings ON public.store_settings FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY admin_settings ON public.store_settings FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));